import urllib.request,json,concurrent.futures,pathlib,hashlib
p=pathlib.Path('intake/evidence'); v=json.load(open('comparison_view.json'))
base='https://raw.githubusercontent.com/'
urls={
'megadock_README':base+'akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/README.md',
'megadock_LICENSE':base+'akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/LICENSE',
