jobs=[(k,u,None) for k,u in urls.items()]
for x in v['inputs']:
 for k in ['receptor_source','ligand_source','reference']: jobs.append((x['id']+'_'+k,x['spec'][k]['url'],x['spec'][k]))
def fetch(job):
 k,u,s=job
 try:
  with urllib.request.urlopen(u,timeout=30) as r: b=r.read(); status=r.status
  # Native reference payloads are deliberately not stored or inspected by intake.
  if s is None: (p/(k+'.txt')).write_bytes(b)
  h=hashlib.sha256(b).hexdigest()
  return dict(id=k,url=u,status=status,bytes=len(b),sha256=h,expected_match=None if s is None else len(b)==s['bytes'] and h==s['sha256'],payload_stored=s is None)
 except Exception as e: return dict(id=k,url=u,error=str(e))
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex: results=list(ex.map(fetch,jobs))
(p/'fetch_results.json').write_text(json.dumps(results,indent=2)+'\\n')
print(json.dumps(results,indent=2))
